package com.bank.stream.service;

import java.util.PriorityQueue;
import java.util.logging.Logger;

// Maintains the Kth largest amount over a growing stream using a size-K min-heap.
public class KthLargestStream {
    private static final Logger log = Logger.getLogger(KthLargestStream.class.getName());
    private final PriorityQueue<Integer> minHeap = new PriorityQueue<>(); // min-heap
    private final int k;

    public KthLargestStream(int k, int[] initial) {
        this.k = k;
        for (int amount : initial) add(amount); // seed via the same path
    }

    public int add(int amount) {
        minHeap.offer(amount);
        if (minHeap.size() > k) minHeap.poll();  // trim back to K largest
        final int kth = minHeap.peek();          // root = Kth largest
        log.fine(() -> "After adding " + amount + ", Kth largest = " + kth);
        return kth;
    }
}
