        KthLargestStream stream = new KthLargestStream(3, new int[]{4000, 1000, 8000, 3000});
        log.info("Add 5000 -> Kth largest: " + stream.add(5000));
        log.info("Add 2000 -> Kth largest: " + stream.add(2000));
        log.info("Add 9000 -> Kth largest: " + stream.add(9000));
    }
}
